-- DC pet-definitions repair: restore the 769 companion pets that exist as
-- items but have no dc_pet_definitions row.
--
-- ROOT CAUSE: the dc_pet_definitions INSERT in
-- 2026_07_11_01_dc_pets_final_batch.sql aborted on apply with MySQL error 1406
-- ("Data too long for column 'variant_color'"). The generator writes the pet's
-- full NAME into variant_color, and 5 rows exceed the column's varchar(30):
--   301836 Palek'ti, the Mouth of Nothingness   (34)
--   301869 Heka'Tarnos, Bringer of Discord      (31)
--   302082 Summon Archetype of Metamorphosis    (33)
--   302084 Summon Archetype of Satisfaction     (32)
--   302244 Summon Archetype of Multiplicity     (32)
-- One bad row aborts the whole multi-row INSERT, but the DELETE immediately
-- before it had already committed -- so every pet in 301778-302560 lost its
-- metadata while item_template (769), npc_vendor (769) and
-- dc_collection_definitions (769) all applied cleanly. Verified live
-- 2026-08-09: dc_pet_definitions had 0 rows in that range.
--
-- FIX: widen variant_color to varchar(100) (it stores a name, same as `name`),
-- then replay the original INSERT verbatim. Idempotent (DELETE-before-INSERT
-- plus ON DUPLICATE KEY UPDATE).
--
-- The generator (retroport_tools/dc_pet_gen_batch.py) now clamps both variant
-- columns to their column widths so this cannot recur.

ALTER TABLE `dc_pet_definitions`
  MODIFY COLUMN `variant_color` varchar(100) DEFAULT NULL;

-- EXCLUDED (deliberately removed from item_template by the 2026-07-13
-- duplicate-of-stock / encrypted-model cleanups; replaying them would
-- create phantom pets with no item behind them):
--   301881, 301882, 301884, 302160, 302177, 302515, 302516, 302538, 302553

DELETE FROM `dc_pet_definitions` WHERE `pet_entry` BETWEEN 301778 AND 302560;
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`pet_spell_id`=VALUES(`pet_spell_id`),`source`=VALUES(`source`),`display_id`=VALUES(`display_id`),`variant_group`=VALUES(`variant_group`),`variant_color`=VALUES(`variant_color`);
